using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;using System.Collections.Generic;
public static class BundledRuntimeChecks {
 static int passed; static readonly List<string> results=new List<string>();
 static void Check(bool yes,string name){if(!yes)throw new Exception(name);passed++;results.Add(name);Console.WriteLine("PASS "+name);}
 static void Fails(Action action,string name){try{action();}catch{Check(true,name);return;}throw new Exception("Expected failure: "+name);}
 static SetupEngine Engine(string root){return new SetupEngine(root,null,false);}
 static void Pair(RuntimePlan p){if(!File.Exists(p.FFmpeg)||!File.Exists(p.FFprobe))throw new Exception("Tool pair missing");}
 public static int Main(string[] args){try{
  AppContext.SetSwitch("Switch.System.IO.UseLegacyPathHandling",false);AppContext.SetSwitch("Switch.System.IO.BlockLongPaths",false);
  string payload=Path.GetFullPath(args[0]),work=Path.GetFullPath(args[1]);Directory.CreateDirectory(work);
  var clean=Engine(Path.Combine(work,"clean"));var plan=clean.Inspect(payload,new[]{"exporter"});bool webviewMissing=plan.NeedWebView2;plan.NeedWebView2=false;
  Check(plan.NeedFFmpeg&&!String.IsNullOrEmpty(plan.BundledFFmpegDir)&&!plan.Downloads.Any(),"clean tools resolved from bundled pair without download");
  clean.EnsureRuntimes(plan,false);Pair(plan);
  Check(SetupEngine.Probe(plan.FFmpeg,"-version").StartsWith("ffmpeg version "+SetupEngine.FFVersion)&&SetupEngine.Probe(plan.FFprobe,"-version").StartsWith("ffprobe version "+SetupEngine.FFVersion),"released pair runs at pinned version");
  string ffdir=Path.GetDirectoryName(Path.GetDirectoryName(plan.FFmpeg));
  Check(Directory.GetFiles(ffdir,"*",SearchOption.AllDirectories).Length==5&&File.Exists(Path.Combine(ffdir,"LICENSE"))&&File.Exists(Path.Combine(ffdir,"README.txt"))&&File.Exists(Path.Combine(ffdir,"THIRD-PARTY-NOTICES.txt"))&&!File.Exists(Path.Combine(Path.GetDirectoryName(plan.FFmpeg),"ffplay.exe")),"two tools and upstream notices only; no ffplay");
  string hash=SetupEngine.Hash(plan.FFmpeg);var write=File.GetLastWriteTimeUtc(plan.FFmpeg);var cached=clean.Inspect(payload,new[]{"exporter"});cached.NeedWebView2=false;clean.EnsureRuntimes(cached,false);
  Check(!cached.NeedFFmpeg&&String.IsNullOrEmpty(cached.BundledFFmpegDir)&&SetupEngine.Hash(cached.FFmpeg)==hash&&File.GetLastWriteTimeUtc(cached.FFmpeg)==write,"existing valid tools retained during upgrade");
  var legacyEngine=Engine(Path.Combine(work,"legacy"));string legacy=Path.Combine(legacyEngine.Tools,"ffmpeg-9.0.1-essentials_build","bin");Directory.CreateDirectory(legacy);foreach(string tool in new[]{"ffmpeg.exe","ffprobe.exe"})File.Copy(Path.Combine(payload,"bin",tool),Path.Combine(legacy,tool));var legacyPlan=legacyEngine.Inspect(payload,new[]{"exporter"});legacyPlan.NeedWebView2=false;legacyEngine.EnsureRuntimes(legacyPlan,false);Check(!legacyPlan.NeedFFmpeg&&Path.GetDirectoryName(legacyPlan.FFmpeg)==legacy&&!Directory.Exists(Path.Combine(legacyEngine.Tools,SetupEngine.FFDirectory)),"legacy valid cache retained without provider migration");
  if(args.Length>2){var fallback=Engine(Path.Combine(work,"cached-download"));Directory.CreateDirectory(fallback.Cache);File.Copy(Path.GetFullPath(args[2]),Path.Combine(fallback.Cache,SetupEngine.FFDirectory+".zip"));var fallbackPlan=fallback.Inspect(payload,new[]{"exporter"});fallbackPlan.BundledFFmpegDir=null;fallbackPlan.NeedWebView2=false;fallback.EnsureRuntimes(fallbackPlan,true);Pair(fallbackPlan);Check(SetupEngine.Hash(fallbackPlan.FFmpeg)==hash&&!File.Exists(Path.Combine(Path.GetDirectoryName(fallbackPlan.FFmpeg),"ffplay.exe"))&&Directory.GetDirectories(fallback.Cache).Length==0,"pinned cached archive fallback installs the same pair and cleans extraction staging without ffplay");}
  var manual=Engine(Path.Combine(work,"manual"));var chosen=manual.Inspect(payload,new[]{"exporter"});manual.UseLocalFFmpeg(chosen,Path.Combine(payload,"bin"));chosen.NeedWebView2=false;manual.EnsureRuntimes(chosen,false);
  Check(String.Equals(Path.GetFullPath(chosen.FFmpeg),Path.GetFullPath(Path.Combine(payload,"bin/ffmpeg.exe")),StringComparison.OrdinalIgnoreCase)&&!Directory.EnumerateFileSystemEntries(manual.Tools).Any(),"manual choice stays external and unchanged");
  var canceled=Engine(Path.Combine(work,"canceled"));var cancelPlan=canceled.Inspect(payload,new[]{"exporter"});cancelPlan.NeedWebView2=false;canceled.Canceled=true;Fails(()=>canceled.EnsureRuntimes(cancelPlan,false),"cancel prevents tool publication");Check(!Directory.Exists(canceled.Tools),"canceled install leaves tool directory absent");
  var disabled=Engine(Path.Combine(work,"disabled"));var disabledPlan=disabled.Inspect(payload,new[]{"timelineNavigator"});disabled.EnsureRuntimes(disabledPlan,false);Check(!Directory.Exists(disabled.Tools),"non-exporter module does not install media tools");
  var bad=Engine(Path.Combine(work,"bad"));string badPayload=Path.Combine(work,"bad-payload");Directory.CreateDirectory(Path.Combine(badPayload,"bin"));File.WriteAllText(Path.Combine(badPayload,"bin/ffmpeg.exe"),"not a valid tool");var badPlan=new RuntimePlan{Payload=badPayload,BundledFFmpegDir=Path.Combine(badPayload,"bin"),NeedFFmpeg=true,Modules=new[]{"exporter"}};Fails(()=>bad.EnsureRuntimes(badPlan,false),"corrupt bundled tool rejected before publication");Check(!Directory.GetDirectories(bad.Tools).Any(),"failed staging reclaimed");
  var incomplete=Engine(Path.Combine(work,"incomplete"));string old=Path.Combine(incomplete.Tools,SetupEngine.FFDirectory);Directory.CreateDirectory(old);File.WriteAllText(Path.Combine(old,"sentinel.txt"),"previous");var incompletePlan=new RuntimePlan{Payload=badPayload,BundledFFmpegDir=Path.Combine(payload,"bin"),NeedFFmpeg=true,Modules=new[]{"exporter"}};Fails(()=>incomplete.EnsureRuntimes(incompletePlan,false),"missing notice aborts replacement");Check(File.ReadAllText(Path.Combine(old,"sentinel.txt"))=="previous"&&Directory.GetDirectories(incomplete.Tools).Length==1,"failed upgrade preserves previous tool directory");
  Console.WriteLine(new JavaScriptSerializer().Serialize(new{passed=passed,systemWebView2Missing=webviewMissing,results=results}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}